/**
 * Collision Response Model Interface
 *
 * Pluggable system for Dynamic ↔ Dynamic collision response.
 * Follows the same pattern as PhysicsModel for consistency.
 *
 * ```js
 * import { collisionResponseRegistry } from '@three-blocks/pro';
 *
 * const CustomResponse = {
 *   name: 'bouncy',
 *   config: { restitution: 0.9, positionCorrection: 1.0 },
 *   resolve( bodyA, bodyB, normal, penetration ) {
 *     // Custom collision response logic
 *   },
 * };
 *
 * collisionResponseRegistry.register( CustomResponse );
 * collisionResponseRegistry.setActiveModel( 'bouncy' );
 * ```
 *
 * @module @three-blocks/pro/physics/models/CollisionResponseModel
 * @short Collision response model interface and validation.
 * @category Physics
 * @tags Collision, Response, Dynamic
 */
/**
 * Collision response configuration
 * @typedef {Object} CollisionResponseConfig
 * @property {number} [restitution=0] - Bounciness factor (0 = no bounce, 1 = perfect bounce)
 * @property {number} [positionCorrection=1] - How much to correct position overlap (0-1)
 */
/**
 * Body state passed to collision response
 * @typedef {Object} CollisionBodyState
 * @property {THREE.Vector3} position - Body position (modified in place)
 * @property {THREE.Vector3} velocity - Body velocity (modified in place)
 * @property {THREE.Vector3} angularVelocity - Angular velocity in radians/sec (modified in place)
 * @property {number} mass - Body mass
 * @property {number} momentOfInertia - Scalar moment of inertia for torque calculation
 * @property {boolean} enableRotationResponse - Whether this body has rotation response enabled
 */
/**
 * Collision Response Model Interface
 *
 * Each collision response preset implements this interface.
 * The engine calls resolve() for each detected Dynamic ↔ Dynamic collision.
 *
 * @typedef {Object} CollisionResponseModel
 * @property {string} name - Unique identifier
 * @property {CollisionResponseConfig} config - Response parameters
 * @property {function(CollisionBodyState, CollisionBodyState, THREE.Vector3, number): void} resolve - Handle collision
 */
/**
 * Validates that an object conforms to the CollisionResponseModel interface
 * @param {Object} model - The model to validate
 * @returns {boolean} - Whether the model is valid
 *
 * @example
 * import { validateCollisionResponseModel } from '@three-blocks/pro';
 * const ok = validateCollisionResponseModel( CustomResponse );
 */
export function validateCollisionResponseModel(model: any): boolean;
/**
 * Collision response configuration
 */
export type CollisionResponseConfig = {
    /**
     * - Bounciness factor (0 = no bounce, 1 = perfect bounce)
     */
    restitution?: number;
    /**
     * - How much to correct position overlap (0-1)
     */
    positionCorrection?: number;
};
/**
 * Body state passed to collision response
 */
export type CollisionBodyState = {
    /**
     * - Body position (modified in place)
     */
    position: THREE.Vector3;
    /**
     * - Body velocity (modified in place)
     */
    velocity: THREE.Vector3;
    /**
     * - Angular velocity in radians/sec (modified in place)
     */
    angularVelocity: THREE.Vector3;
    /**
     * - Body mass
     */
    mass: number;
    /**
     * - Scalar moment of inertia for torque calculation
     */
    momentOfInertia: number;
    /**
     * - Whether this body has rotation response enabled
     */
    enableRotationResponse: boolean;
};
/**
 * Collision Response Model Interface
 *
 * Each collision response preset implements this interface.
 * The engine calls resolve() for each detected Dynamic ↔ Dynamic collision.
 */
export type CollisionResponseModel = {
    /**
     * - Unique identifier
     */
    name: string;
    /**
     * - Response parameters
     */
    config: CollisionResponseConfig;
    /**
     * - Handle collision
     */
    resolve: (arg0: CollisionBodyState, arg1: CollisionBodyState, arg2: THREE.Vector3, arg3: number) => void;
};
